{
  "name": "串口设备",
  "name_en": "Serial device",
  "manufacturer": "",
  "description": "通过 RS-232、RS-485 或 TTL 等串行接口与计算机通信的仪器、控制器或传感器。在实验室中常用于发送控制命令、读取测量数据，以及按字节或按行交换文本或二进制数据。",
  "description_en": "An instrument, controller, or sensor that communicates with a computer through a serial interface such as RS-232, RS-485, or TTL. In laboratories it is commonly used to send control commands, read measurement data, and exchange text or binary data byte-by-byte or line-by-line.",
  "tag_hints": [
    "serial communication",
    "RS-232",
    "RS-485",
    "TTL serial",
    "instrument control",
    "data acquisition",
    "asynchronous I/O"
  ],
  "actions": [
    {
      "action_name": "auto-loop",
      "description": "获取/设置异步事件循环",
      "description_en": "Get/set the asynchronous event loop"
    },
    {
      "action_name": "auto-read_async",
      "description": "异步读取指定字节数的数据",
      "description_en": "Asynchronously read a specified number of bytes"
    },
    {
      "action_name": "auto-read_until_async",
      "description": "异步读取数据直到遇到指定结束符或达到长度限制",
      "description_en": "Asynchronously read data until the expected terminator is found or a size limit is reached"
    },
    {
      "action_name": "auto-readinto_async",
      "description": "异步将读取的数据写入给定缓冲区",
      "description_en": "Asynchronously read data into a provided buffer"
    },
    {
      "action_name": "auto-readline_async",
      "description": "异步读取一行数据",
      "description_en": "Asynchronously read one line of data"
    },
    {
      "action_name": "auto-readlines_async",
      "description": "异步读取多行数据",
      "description_en": "Asynchronously read multiple lines of data"
    },
    {
      "action_name": "auto-write_async",
      "description": "异步写入数据",
      "description_en": "Asynchronously write data"
    },
    {
      "action_name": "auto-writelines_async",
      "description": "异步写入多行数据",
      "description_en": "Asynchronously write multiple lines of data"
    }
  ]
}

